//! Per-job private staging roots for generated cheat installs.
//!
//! Every adapter stages its generated bytes under a fixed directory
//! (`generated-cheats`, `generated-dolphin`, ...) using a file name derived
//! from the destination. Two installs of the same content - or two jobs that
//! resolve to the same file name - therefore used to share one staged path
//! and one fixed `.partial` temporary: concurrent stagers raced on the
//! rename, and a later job could replace the bytes an earlier, already
//! reviewed job was about to install. Each job now stages into its own
//! uniquely named subdirectory, so staged paths, temporaries and the approved
//! source root are never shared between jobs.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const JOB_DIR_PREFIX: &str = "job-";
/// A reviewed preview this old is long past any freshness window, so its
/// private staging directory is safe to retire.
const STALE_JOB_AGE: Duration = Duration::from_secs(24 * 60 * 60);

static NEXT_JOB: AtomicU64 = AtomicU64::new(0);

/// Returns a not-yet-existing, uniquely named staging root under `base`
/// (pid + nanosecond clock + process-wide counter), and best-effort retires
/// stale sibling job directories. Nothing is created here: the stager's own
/// `create_dir_all` creates it.
#[must_use]
pub fn new_staging_job_root(base: &Path) -> PathBuf {
    retire_stale_staging_jobs(base);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|elapsed| elapsed.as_nanos())
        .unwrap_or(0);
    let sequence = NEXT_JOB.fetch_add(1, Ordering::Relaxed);
    base.join(format!(
        "{JOB_DIR_PREFIX}{}-{nanos:x}-{sequence:x}",
        std::process::id()
    ))
}

fn retire_stale_staging_jobs(base: &Path) {
    let Ok(entries) = fs::read_dir(base) else {
        return;
    };
    for entry in entries.flatten() {
        let name = entry.file_name();
        if !name.to_string_lossy().starts_with(JOB_DIR_PREFIX) {
            continue;
        }
        // `symlink_metadata`: never follow a link out of the staging base.
        let Ok(metadata) = fs::symlink_metadata(entry.path()) else {
            continue;
        };
        if !metadata.is_dir() {
            continue;
        }
        let stale = metadata
            .modified()
            .ok()
            .and_then(|modified| SystemTime::now().duration_since(modified).ok())
            .is_some_and(|age| age > STALE_JOB_AGE);
        if stale {
            let _ = fs::remove_dir_all(entry.path());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roots_are_unique_and_not_created() {
        let dir = tempfile::tempdir().unwrap();
        let a = new_staging_job_root(dir.path());
        let b = new_staging_job_root(dir.path());
        assert_ne!(a, b);
        assert_eq!(a.parent(), Some(dir.path()));
        assert!(!a.exists());
    }

    #[test]
    fn only_stale_job_directories_are_retired() {
        let dir = tempfile::tempdir().unwrap();
        let old = dir.path().join("job-1-0-0");
        let fresh = dir.path().join("job-2-0-0");
        let unrelated = dir.path().join("keep-me");
        for path in [&old, &fresh, &unrelated] {
            fs::create_dir(path).unwrap();
            fs::write(path.join("f"), b"x").unwrap();
        }
        let long_ago = SystemTime::now() - STALE_JOB_AGE * 2;
        fs::File::open(&old)
            .unwrap()
            .set_modified(long_ago)
            .unwrap();
        fs::File::open(&unrelated)
            .unwrap()
            .set_modified(long_ago)
            .unwrap();
        let _ = new_staging_job_root(dir.path());
        assert!(!old.exists());
        assert!(fresh.exists());
        assert!(
            unrelated.exists(),
            "non job-* directories are never touched"
        );
    }
}
